","// Service layer for brunch items API calls
export class BrunchService {
 constructor() {
 this.brunchItemsTable = 'x_undul_brunch_app_brunch_items';
 this.dietaryLabelsTable = 'x_undul_brunch_app_dietary_labels';
 }

 async getBrunchItems(searchTerm = '', category = '', labels = []) {
 let query = `?sysparm_display_value=all&sysparm_limit=100`;
 let conditions = [];

 // Add search filter
 if (searchTerm) {
 conditions.push(`item_nameCONTAINS${encodeURIComponent(searchTerm)}`);
 }

 // Add category filter
 if (category) {
 conditions.push(`category=${encodeURIComponent(category)}`);
 }

 // Add labels filter - check if any selected labels are in the item's labels
 if (labels.length > 0) {
 const labelConditions = labels.map(labelId => 
 `labelsCONTAINS${encodeURIComponent(labelId)}`
 );
 conditions.push(`(${labelConditions.join('^OR')})`);
 }

 if (conditions.length > 0) {
 query += `&sysparm_query=${conditions.join('^')}`;
 }

 try {
 const response = await fetch(`/api/now/table/${this.brunchItemsTable}${query}`, {
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });

 if (!response.ok) {
 const errorText = await response.text();
 console.error('Brunch items fetch failed:', response.status, errorText);
 throw new Error(`Failed to fetch brunch items (${response.status}): ${response.statusText}`);
 }

 const data = await response.json();
 return data.result || [];
 } catch (error) {
 console.error('Error fetching brunch items:', error);
 throw error;
 }
 }

 async createBrunchItem(itemData) {
 try {
 const response = await fetch(`/api/now/table/${this.brunchItemsTable}?sysparm_display_value=all`, {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 },
 body: JSON.stringify(itemData)
 });

 if (!response.ok) {
 const error = await response.json();
 throw new Error(error.error?.message || 'Failed to create brunch item');
 }

 return await response.json();
 } catch (error) {
 console.error('Error creating brunch item:', error);
 throw error;
 }
 }

 async deleteBrunchItem(sysId) {
 try {
 const response = await fetch(`/api/now/table/${this.brunchItemsTable}/${sysId}`, {
 method: 'DELETE',
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });

 return response.ok;
 } catch (error) {
 console.error('Error deleting brunch item:', error);
 throw error;
 }
 }

 async getDietaryLabels() {
 try {
 const response = await fetch(`/api/now/table/${this.dietaryLabelsTable}?sysparm_display_value=all&sysparm_limit=100`, {
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });

 if (!response.ok) {
 const errorText = await response.text();
 console.error('Dietary labels fetch failed:', response.status, errorText);
 throw new Error(`Failed to fetch dietary labels (${response.status}): ${response.statusText}`);
 }

 const data = await response.json();
 console.log('Dietary labels loaded:', data.result?.length || 0, 'items');
 return data.result || [];
 } catch (error) {
 console.error('Error fetching dietary labels:', error);
 throw error;
