// Translation utility hook
export const useTranslation = (language = 'en') => {
 const t = (key, params = {}) => {
 const keys = key.split('.');
 let value = translations[language];

 for (const k of keys) {
 value = value?.[k];
 }

 if (value === undefined) {
 // Fallback to English if translation not found
 value = translations.en;
 for (const k of keys) {
 value = value?.[k];
 }
 }

 // Replace parameters in the translation
 if (typeof value === 'string' && Object.keys(params).length > 0) {
 return value.replace(/\{\{(\w+)\}\}/g, (match, param) => params[param] || match);
 }

 return value || key;
 };

 return { t };
};

// Language detection and storage
export const getStoredLanguage = () => {
 try {
 return localStorage.getItem('brunch-app-language') || 'en';
 } catch (e) {
 return 'en';
 }
};

export const setStoredLanguage = (language) => {
 try {
 localStorage.setItem('brunch-app-language', language);
 } catch (e) {
 // Ignore storage errors
 }
};

export const getAvailableLanguages = () => [
 { code: 'en', name: 'English', flag: '' },
 { code: 'fr', name: 'Français', flag: '' }
];

// Dietary label translation mapping
export const translateDietaryLabel = (labelName, language = 'en') => {
 const dietaryTranslations = {
 en: {
 'Halal': 'Halal',
 'Vegan': 'Vegan',
 'Vegetarian': 'Vegetarian',
 'Gluten-free': 'Gluten-free'
 },
 fr: {
 'Halal': 'Halal',
 'Vegan': 'Végétalien',
 'Vegetarian': 'Végétarien',
 'Gluten-free': 'Sans gluten'
 }
 };

 return dietaryTranslations[language]?.[labelName] || labelName;
};","export default function _qi(n,e="style"){if(!(!n||typeof window>"u")){if(e==="style"){let s=document.createElement("style");s.setAttribute("type","text/css"),s.innerHTML=n,document.head.appendChild(s)}else if(e==="link"){let s=document.createElement("link");s.setAttribute("rel","stylesheet"),s.setAttribute("href",n),document.head.appendChild(s)}return n}}","import React, { useState, useEffect } from 'react';
