 }

 // Check if user can delete this item - with null safety
 const canDelete = (userRoles && userRoles.includes('x_undul_brunch_app.brunch_coordinator')) || 
 (currentUser && currentUser.sys_id && value(item.participant_name) === currentUser.sys_id);

 const handleDelete = async () => {
 if (!canDelete) return;

 if (window.confirm(t('deleteConfirm'))) {
 try {
 await service.deleteBrunchItem(value(item.sys_id));
 onDelete();
 } catch (error) {
 alert(`${t('deleteError')}: ${error.message}`);
 }
 }
 };

 const categoryLabels = {
 'appetizer': ` ${t('categories.appetizer')}`,
 'drinks': ` ${t('categories.drinks')}`,
 'cheese': ` ${t('categories.cheese')}`, 
