 'savory_pies': ` ${t('categories.savory_pies')}`,
 'salad': ` ${t('categories.salad')}`,
 'dessert': ` ${t('categories.dessert')}`,
 'other': `️ ${t('categories.other')}`
 };

 // Helper function to translate dietary labels string
 const translateLabelsString = (labelsString, language) => {
 if (!labelsString) return '';
 return labelsString
 .split(',')
 .map(label => translateDietaryLabel(label.trim(), language))
 .join(', ');
 };

 // Render list view (compact)
 if (viewMode === 'list') {
 return (
 <div className="brunch-item-list">
