 <span className="item-category-compact">
 {categoryLabels[display(item.category)] || display(item.category)}
 </span>
 </div>
 <div className="item-meta">
 <span className="item-participant-compact">
 {display(item.participant_name)}
 </span>
 {display(item.labels) && (
 <span className="item-labels-compact">
 ️ {translateLabelsString(display(item.labels), language)}
 </span>
 )}
 </div>
 {canDelete && (
 <button 
 className="delete-button-compact"
 onClick={handleDelete}
 title={t('delete')}
 >
 ️
 </button>
 )}
 </div>
 {display(item.description) && (
 <div className="item-description-compact">
 {display(item.description)}
 </div>
 )}
 </div>
 );
 }

 // Default card view
 return (
 <div className="brunch-item">
 <div className="item-header">
 <h3 className="item-name">
 <span className="item-icon">️</span>
 {display(item.item_name)}
 </h3>
 {canDelete && (
 <button 
 className="delete-button"
 onClick={handleDelete}
 title={t('delete')}
 >
 ️
 </button>
 )}
 </div>

 <div className="item-details">
 <div className="item-category">
 <span className="detail-icon"></span>
 <strong>{t('category')}:</strong> {categoryLabels[display(item.category)] || display(item.category)}
 </div>

 <div className="item-participant">
 <span className="detail-icon"></span>
 <strong>{t('broughtBy')}:</strong> {display(item.participant_name)}
 </div>

 {display(item.labels) && (
 <div className="item-labels">
 <span className="detail-icon">️</span>
 <strong>{t('labels')}:</strong> {translateLabelsString(display(item.labels), language)}
 </div>
 )}

 {display(item.description) && (
 <div className="item-description">
 <span className="detail-icon"></span>
 <strong>{t('description')}:</strong> {display(item.description)}
 </div>
 )}
 </div>
 </div>
 );
}

