import { BrunchService } from './services/BrunchService.js';
import BrunchForm from './components/BrunchForm.jsx';
import BrunchItemsList from './components/BrunchItemsList.jsx';
import SearchFilters from './components/SearchFilters.jsx';
import LanguageSelector from './components/LanguageSelector.jsx';
import ViewModeSelector from './components/ViewModeSelector.jsx';
import { useTranslation, getStoredLanguage, setStoredLanguage } from './i18n/translations.js';
import './app.css';

export default function App() {
 const service = useMemo(() => new BrunchService(), []);
 const [brunchItems, setBrunchItems] = useState([]);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(null);
 const [searchTerm, setSearchTerm] = useState('');
 const [selectedCategory, setSelectedCategory] = useState('');
 const [selectedLabels, setSelectedLabels] = useState([]);
 const [currentUser, setCurrentUser] = useState(null);
 const [userRoles, setUserRoles] = useState([]);
 const [language, setLanguage] = useState(getStoredLanguage());
 const [viewMode, setViewMode] = useState(() => {
 try {
 return localStorage.getItem('brunch-app-view-mode') || 'card';
 } catch (e) {
 return 'card';
 }
 });

 const { t } = useTranslation(language);

 const loadBrunchItems = async () => {
 try {
 setLoading(true);
 setError(null);
 const items = await service.getBrunchItems(searchTerm, selectedCategory, selectedLabels);
 // Filter out any null or invalid items
 const validItems = items.filter(item => item && item.sys_id);
 setBrunchItems(validItems);
 } catch (err) {
 setError(err.message);
 console.error('Failed to load brunch items:', err);
 // Set empty array to prevent component errors
 setBrunchItems([]);
 } finally {
 setLoading(false);
 }
 };

 useEffect(() => {
 // Load user information first, then brunch items
 const initializeApp = async () => {
 try {
 const [user, roles] = await Promise.all([
 service.getCurrentUser(),
 service.getCurrentUserRoles()
 ]);
 setCurrentUser(user);
 setUserRoles(roles);
 } catch (err) {
 console.error('Failed to load user info:', err);
 // Set defaults to prevent null errors
 setCurrentUser({ sys_id: '', name: 'Current User', user_name: 'current_user' });
 setUserRoles([]);
 }

 // Load brunch items after user info is loaded
 loadBrunchItems();
 };

 initializeApp();
 }, [searchTerm, selectedCategory, selectedLabels]);

 const handleItemAdded = () => {
 loadBrunchItems();
 };

 const handleItemDeleted = () => {
 loadBrunchItems();
 };

 const handleLanguageChange = (newLanguage) => {
 setLanguage(newLanguage);
 setStoredLanguage(newLanguage);
 };

 const handleViewModeChange = (newViewMode) => {
 setViewMode(newViewMode);
 // Optionally store in localStorage
 try {
 localStorage.setItem('brunch-app-view-mode', newViewMode);
 } catch (e) {
 // Ignore storage errors
 }
 };

 return (
 <div className="brunch-app">
 <header className="brunch-header">
 <div className="header-controls">
 <LanguageSelector 
 currentLanguage={language}
 onLanguageChange={handleLanguageChange}
 t={t}
 />
 <ViewModeSelector
 viewMode={viewMode}
 onViewModeChange={handleViewModeChange}
 t={t}
 />
 </div>

 <h1>
 <span className="header-icon"></span>
 {t('appTitle')}
 </h1>
 <p>
 <span className="description-icon">✨</span>
 {t('appDescription')}
 </p>
 {userRoles && userRoles.includes('x_undul_brunch_app.brunch_coordinator') && (
 <div className="coordinator-badge">
 <span className="badge-icon"></span>
 {t('coordinatorBadge')}
 </div>
 )}
 </header>

 <div className="brunch-container">
 <div className="brunch-form-panel">
 <BrunchForm 
 service={service} 
 onItemAdded={handleItemAdded}
 t={t}
 language={language}
 />
 </div>

 <div className="brunch-list-panel">
 <SearchFilters
 searchTerm={searchTerm}
 onSearchChange={setSearchTerm}
 selectedCategory={selectedCategory}
 onCategoryChange={setSelectedCategory}
 selectedLabels={selectedLabels}
 onLabelsChange={setSelectedLabels}
 service={service}
 t={t}
 language={language}
 />

 {error && (
 <div className="error-message">
 <span className="error-icon">⚠️</span>
 <p><strong>{t('errorLoading')}:</strong> {error}</p>
 <p><small>{t('permissionsNote')}</small></p>
 <button onClick={loadBrunchItems} className="retry-button">
 {t('retry')}
 </button>
 </div>
 )}

 <BrunchItemsList
 items={brunchItems}
 loading={loading}
 onItemDeleted={handleItemDeleted}
 service={service}
 currentUser={currentUser || { sys_id: '' }}
 userRoles={userRoles || []}
 viewMode={viewMode}
 t={t}
 language={language}
 />
 </div>
 </div>
 </div>
 );
